377	    <header>
378	        <div class="header-container">
379	            <h1>Welcome</h1>
380	            <button class="menu-toggle" aria-label="Toggle navigation menu" aria-controls="nav-menu" aria-expanded="false">☰</button>
381	            <nav aria-label="Primary navigation">
382	                <ul id="nav-menu">
383	                    <li><a href="#features">Features</a></li>
384	                    <li><a href="#get-started">Get Started</a></li>
385	                </ul>
386	            </nav>
387	        </div>
388	    </header>
389	
390	    <main id="main-content">
391	        <article>
392	            <h2>Modern Web Template</h2>
393	            <p>This is an improved HTML template built with best practices for performance, accessibility, and maintainability.</p>
394	        </article>
395	
396	        <article id="features">
397	            <h2>Key Features</h2>
398	            <p>
399	                This template includes semantic HTML elements, responsive design, modern CSS with gradients,
400	                proper meta tags for SEO, and accessibility considerations to create a solid foundation for any web project.
401	            </p>
402	            <ul class="feature-list">
403	                <li>Semantic HTML5 structure</li>
404	                <li>WCAG 2.1 accessibility compliance</li>
405	                <li>Mobile-first responsive design</li>
406	                <li>Keyboard navigation support</li>
407	                <li>Open Graph meta tags</li>
408	            </ul>
409	            <button type="button" class="cta-button" id="learn-more-btn" aria-label="Learn more and contact us">Learn More</button>
410	        </article>
411	
412	        <article id="get-started">
413	            <h2>Get Started</h2>
414	            <p>
415	                Use this template as a foundation for your next project. It's clean, well-structured, and ready to be
416	                customized to meet your specific needs.
417	            </p>
418	            <form id="contact-form" method="POST">
419	                <fieldset>
420	                    <legend>Get in Touch</legend>
421	                    <div class="form-group">
422	                        <label for="name">Name</label>
423	                        <input type="text" id="name" name="name" required>
424	                    </div>
425	                    <div class="form-group">
426	                        <label for="email">Email</label>
427	                        <input type="email" id="email" name="email" required>
428	                    </div>
429	                    <button type="submit" class="cta-button">Send Message</button>
430	                </fieldset>
431	            </form>
432	        </article>
433	    </main>
434	
435	    <footer>
436	        <p>&copy; 2026 Modern Web Template. All rights reserved.</p>
437	        <nav aria-label="Footer links">
438	            <ul>
439	                <li><a href="/privacy/">Privacy Policy</a></li>
440	                <li><a href="/terms/">Terms of Service</a></li>
441	            </ul>
442	        </nav>
443	    </footer>
444	
445	    <script type="application/ld+json">
446	    {
447	        "@context": "https://schema.org",
448	        "@type": "WebSite",
449	        "name": "Modern Web Template",
450	        "description": "A modern, accessible website built with best practices",
451	        "url": "https://example.com/",
452	        "author": {
453	            "@type": "Organization",
454	            "name": "Web Developer"
455	        },
456	        "mainEntity": {
457	            "@type": "CreativeWork",
458	            "name": "Modern Web Template",
459	            "description": "A semantic HTML5 template with accessibility and responsive design"
460	        }
461	    }
462	    </script>
463	
464	    <script>
465	        document.addEventListener('DOMContentLoaded', function() {
466	            const menuToggle = document.querySelector('.menu-toggle');
467	            const navMenu = document.getElementById('nav-menu');
468	
469	            if (menuToggle) {
470	                menuToggle.addEventListener('click', function() {
471	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
472	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
473	                    navMenu.toggleAttribute('hidden');
474	                });
475	
476	                const navLinks = navMenu.querySelectorAll('a');
477	                navLinks.forEach(link => {
478	                    link.addEventListener('click', function() {
479	                        menuToggle.setAttribute('aria-expanded', 'false');
480	                        navMenu.setAttribute('hidden', '');
481	                    });
482	                });
483	            }
484	
485	            const learnMoreBtn = document.getElementById('learn-more-btn');
486	            if (learnMoreBtn) {
487	                learnMoreBtn.addEventListener('click', function() {
488	                    const getStartedSection = document.getElementById('get-started');
489	                    if (getStartedSection) {
490	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
491	                        getStartedSection.querySelector('#name').focus();
492	                    }
493	                });
494	            }
495	
496	            const contactForm = document.getElementById('contact-form');
497	            if (contactForm) {
498	                contactForm.addEventListener('submit', function(e) {
499	                    e.preventDefault();
500	                    alert('Thank you for your message! This is a demo form.');
501	                    contactForm.reset();
502	                });
503	            }
504	        });
505	    </script>
506	</body>
507	</html>
